                    (click)="setFilter('all')">All</button>
                <button type="button" class="chip" [class.active]="filter() === 'unwatched'"
                    [attr.aria-pressed]="filter() === 'unwatched' ? 'true' : 'false'"
                    (click)="setFilter('unwatched')">To watch</button>
                <button type="button" class="chip" [class.active]="filter() === 'watched'"
                    [attr.aria-pressed]="filter() === 'watched' ? 'true' : 'false'"
                    (click)="setFilter('watched')">Watched</button>
            </div>
            <button type="button" class="chip sort-a-z" [class.active]="sortAZ()"
                [attr.aria-pressed]="sortAZ() ? 'true' : 'false'" (click)="toggleSortAZ()">A–Z</button>
            @if (watchedCount() > 0) {
                <button type="button" class="clear-watched" (click)="clearWatched()">Clear watched</button>
            }
        </div>

        @if (visibleMovies().length === 0) {
            <p class="no-match">No movies match this filter.</p>
